import os


class CliCallFormatter(object):
    """
    Class used to generate CLI call strings.
    """
    def __init__(self, *executable_cli_parts):
        """
        Initialize newly created instance of `CliCallFormatter`.

        :param executable_cli_parts: list of strings consisting of CLI call parts
                                     needed in order to properly call executable/script
                                     itself without any additional parameters/flags/arguments.
                                     I.e. fullpath to executable of fullpath to interpreter
                                     executable and fullpath to script to be run in said
                                     interpreter.
        """
        self._executable_cli_parts = executable_cli_parts
        self._options = {}
        self._positional_arguments = []

    def set_option(self, option_name, option_value=None):
        """
        Set option/flag of call with ability to set optional value.

        :param option_name: name of the option/flag to be set.
        :param option_value: optional value to be set for the option/flag.
                             If its value is `None`, then the option/flag
                             will be just 'set', without passing any value
                             to it.
        """
        self._options[option_name] = option_value

    def set_positional_arguments(self, *pos_args):
        """
        Set positional arguments (placed after options) in CLI call.

        :param pos_args: list of strings making all "positional arguments"
                         of the CLI call.
        """
        self._positional_arguments = list(pos_args)

    def generate_cli_call_string(self):
        """
        Generate CLI call string using current configuration/state of this object.

        :return: string with generated CLI call
        """
        cli_call = list(self._executable_cli_parts)

        for option_name, option_value in self._options.items():
            option_marker_chars = '-' if len(option_name) == 1 else "--"

            cli_call.append("{}{}".format(option_marker_chars, option_name))
            if option_value is not None:
                cli_call.append(''.join(['"', str(option_value), '"']))

        cli_call.extend(self._positional_arguments)

        return ' '.join(cli_call)


class CapsScriptCliCallFormatter(object):
    """
    Class used to generate strings with CLI calls for CAPSCLI Python script.
    """
    def __init__(self,
                 python_executable_filepath,
                 caps_script_filepath,
                 caps_token_filepath):
        """
        Initialize newly created instance of class `CapsScriptCliCallFormatter`.

        :param python_executable_filepath: filepath string to the interpreter
                                           executable of the Python that one
                                           wants to use for CAPS script calls.
        :param caps_script_filepath: filepath string to the CAPSSLI Python script
                                     one wants to use.
        :param caps_token_filepath: filepath string to the file containing 'token'
                                    to be used in CAPSCLI calls.
        """
        self._python_executable_filepath = python_executable_filepath
        self._caps_script_filepath = caps_script_filepath
        self._caps_token_filepath = caps_token_filepath

    def _set_common_options(self, cli_call_gen_inst):
        """
        Set common options, i.e. options shared between CAPS script's main commands.

        :param cli_call_gen_inst: instance of `CliCallFormatter` to be used for
                                  setting mentioned options.
        """
        cli_call_gen_inst.set_option("cert", self._caps_token_filepath)

    def create_caps_upload_call(self, filepath, config_file):
        """
        Create and return string representation of CAPSCLI Python script call
        of upload functionality.

        :param config_file:
        :param filepath:
        :param snapshot_filepath: filepath string to snapshot archive to be uploaded.
        :param customer: string/int representing Customer ID in the CAPS system.
        :param product: string/int representing Customer ID in the CAPS system.
        :param description: string with description of the uploaded snapshot.
        :param purpose: string describing purpose of uploading the snapshot.
        :param service: ID string to indicate with which 'service' in the CAPS
                        system should uploaded snapshot be associated with.
        :param retention: int/string indicating how many days should uploaded
                          snapshot be stored on the CAPS system for.
        :param classification: ID string/int to indicate with which classification
                               should the uploaded snapshot be associated with.
        :param ticket_app: optional parameter to specify string ID as a 'ticket app'
                            for CAPS.
        :param ticket_hash: optional parameter to specify string hash as a 'ticket'
                            for CAPS.

        :return: string of generated CLI call.
        """
        cli_call_gen = CliCallFormatter(self._python_executable_filepath,
                                        self._caps_script_filepath,
                                        "ul")
        self._set_common_options(cli_call_gen)
        cli_call_gen.set_option("config", config_file)
        cli_call_gen.set_positional_arguments(filepath)
        return cli_call_gen.generate_cli_call_string()

    def create_caps_list_call(self, attach_id, config_file):
        """
        Create and return string representation of CAPSCLI Python script call
        of list functionality.

        :param attach_id: hash string used to identify uploaded snapshot archive
                          in the CAPS.

        :return: string of generated CLI call.
        """
        cli_call_gen = CliCallFormatter(self._python_executable_filepath,
                                        self._caps_script_filepath,
                                        "ls")
        self._set_common_options(cli_call_gen)
        cli_call_gen.set_option("attachid", attach_id)
        cli_call_gen.set_option("config", config_file)

        return cli_call_gen.generate_cli_call_string()

    def create_caps_download_call(self,
                                  attach_id,
                                  download_target_filenames,
                                  download_destination_dirpath):
        """
        Create and return string representation of CAPSCLI Python script call
        of download functionality.

        :param attach_id: hash string used to identify uploaded snapshot archive
                          in the CAPS.
        :param download_target_filenames: string of comma-separated filenames of
                                          files to be downloaded from CAPS.
        :param download_destination_dirpath: path string pointing to directory
                                             where downloaded files should be.

        :return: string of generated CLI call.
        """
        cli_call_gen = CliCallFormatter(self._python_executable_filepath,
                                        self._caps_script_filepath,
                                        "dl")
        self._set_common_options(cli_call_gen)
        cli_call_gen.set_option("attachid", attach_id)
        if download_target_filenames is not None:
            cli_call_gen.set_option("dlfiles", download_target_filenames)
        if download_destination_dirpath is not None:
            cli_call_gen.set_option("dldir", os.path.join(download_destination_dirpath, ""))
        cli_call_gen.set_option("qa")
        return cli_call_gen.generate_cli_call_string()

    def create_caps_delete_call(self, attach_id, config_file):
        """
        Create and return string representation of CAPSCLI Python script call
        of delete functionality.

        :param attach_id: hash string used to identify uploaded snapshot archive
                          in the CAPS.
        :return: string of generated CLI call.
        """
        cli_call_gen = CliCallFormatter(self._python_executable_filepath,
                                        self._caps_script_filepath,
                                        "del")
        self._set_common_options(cli_call_gen)
        cli_call_gen.set_option("attachid", attach_id)
        cli_call_gen.set_option("config", config_file)
        return cli_call_gen.generate_cli_call_string()
